package fr.roadguard.app;
/** Viewport-only adapter: does not replace or modify any map renderer or camera. */
final class RadarViewport {
 static final String QUERY = "(function(){try{\n var lat,lon,neLat,neLon;\n if(typeof map!=='undefined'&&map&&typeof map.getBounds==='function'){\n  var b=map.getBounds(),c=b.getCenter(),ne=b.getNorthEast();\n  lat=Number(c.lat);lon=Number(c.lng);neLat=Number(ne.lat);neLon=Number(ne.lng);\n }else if(typeof minLat==='number'&&typeof maxLat==='number'&&typeof minLon==='number'&&typeof maxLon==='number'&&typeof scale==='number'&&scale>0&&typeof panX==='number'&&typeof panY==='number'&&innerWidth>0&&innerHeight>0){\n  lon=minLon+(.5-panX/(innerWidth*scale))*(maxLon-minLon);\n  lat=maxLat-(.5-panY/(innerHeight*scale))*(maxLat-minLat);\n  neLon=lon+(maxLon-minLon)/(2*scale);neLat=lat+(maxLat-minLat)/(2*scale);\n }else return null;\n if(![lat,lon,neLat,neLon].every(Number.isFinite)||Math.abs(lat)>90||Math.abs(lon)>180)return null;\n var rad=Math.PI/180,dLat=(neLat-lat)*rad,dLon=(neLon-lon)*rad;\n var a=Math.sin(dLat/2)*Math.sin(dLat/2)+Math.cos(lat*rad)*Math.cos(neLat*rad)*Math.sin(dLon/2)*Math.sin(dLon/2);\n var distance=6371000*2*Math.atan2(Math.sqrt(Math.max(0,Math.min(1,a))),Math.sqrt(Math.max(0,1-a)));\n return [lat,lon,Math.min(60000,Math.max(2500,distance*1.24))];\n }catch(e){return null;}})()";
 static final String INSTALL = "(function(){try{\n if(window.__roadguardRadarViewportBound)return;\n var timer;function changed(){clearTimeout(timer);timer=setTimeout(function(){if(window.RoadguardMap&&typeof window.RoadguardMap.refreshRadars==='function')window.RoadguardMap.refreshRadars();},180);}\n if(typeof map!=='undefined'&&map&&typeof map.getBounds==='function'){\n  if(typeof map.getBounds().pad==='function')return; // Leaflet already installs its refresh callback.\n  if(typeof map.on!=='function')return;\n  map.on('moveend',changed);map.on('zoomend',changed);\n }else if(typeof xy==='function'&&typeof scale==='number'){\n  ['pointerup','touchend','mouseup','wheel','resize'].forEach(function(name){window.addEventListener(name,changed,{passive:true});});\n }else return;\n window.__roadguardRadarViewportBound=true;\n }catch(e){}})()";
 private RadarViewport(){}
}
